function rlog(who_,txt){I.run.log.push([nowT(),who_,txt]);audit("runbook "+I.run.rb,txt)}
function tick(run){if(I.run!==run||run.st!=="running")return;run.i++;const rb=rbOf(run.rb);if(run.i>=rb.steps.length){run.st="done";rlog("Ops Agent","Run completed. "+(run.dry?"Dry run, nothing changed.":"All steps succeeded."));rb.last="Today";toast(rb.ref+" completed");paintRun();return}
 const s=rb.steps[run.i];if(s.t!=="auto"){run.steps[run.i]="wait";run.st="waiting";rlog("Ops Agent",`Step ${run.i+1} waiting: ${s.t==="approval"?"approval gate":"manual action"}`);paintRun();return}
 run.steps[run.i]="running";paintRun();setTimeout(()=>{if(I.run!==run||run.st==="aborted")return;run.steps[run.i]="done";rlog("Ops Agent",`Step ${run.i+1} ${run.dry?"would run":"succeeded"}: ${s.x}`);paintRun();tick(run)},1000)}
function rollback(run,why){const rb=rbOf(run.rb);run.st="rollback";rlog(who(),why);paintRun();const idx=run.steps.map((s,i)=>s==="done"?i:-1).filter(i=>i>=0).reverse();let k=0;const nx=()=>{if(I.run!==run)return;if(k>=idx.length){run.st="aborted";run.steps=run.steps.map(s=>s==="wait"||s==="running"?"fail":s);rlog("Ops Agent","Rollback complete: "+rb.rb);toast("Rolled back "+rb.ref,"warn");paintRun();return}rlog("Ops Agent","Rolling back step "+(idx[k]+1));k++;paintRun();setTimeout(nx,550)};setTimeout(nx,400)}
function startRun(rb,p,dry,link){const run={rb:rb.id,steps:rb.steps.map(()=>"pending"),i:-1,st:"running",dry,log:[]};I.run=run;I.rbSel=rb.id;rlog(who(),`Started ${rb.ref} ${dry?"as a dry run ":""}with ${Object.entries(p).map(e=>e[0]+"="+e[1]).join(", ")||"no parameters"}${link?" for "+link:""}`);if(S.screen!=="itom_run")go("itom_run");else render();setTimeout(()=>{paintRun();tick(run)},50)}
function runForm(rb){const f=[{k:"__link",label:"Link this run to",type:"select",opts:[["","Nothing"]].concat(rb.links.inc.map(i=>[i,"Incident "+i])).concat(rb.links.ev.map(g=>[g,"Event group "+g+": "+GRP.find(x=>x.id===g).n]))},...rb.params.map(p=>({k:"p_"+p.k,label:p.k,type:"text",req:true,help:"Parameter"})),{k:"__dry",label:"Dry run (log only, change nothing)",type:"toggle"}];const d={__dry:rb.risk==="High"&&false,__link:rb.links.inc[0]||""};rb.params.forEach(p=>d["p_"+p.k]=p.d);
 OF({id:"itom_runf",title:"Run "+rb.ref,story:`This runs ${rb.steps.length} steps. ${rb.steps.filter(s=>s.t==="approval").length?"It pauses at each approval gate until an eligible person approves. ":""}Every step is written to the audit trail, and you can abort to run the rollback: ${rb.rb}.`,submit:"Start run",fields:f,defaults:d,
 liveH:v=>`<b>Blast radius check:</b> risk is ${rb.risk}. ${rb.risk==="High"?"A second approver is required for the gate.":"Normal approval path."} Average duration ${rb.avg}, success rate ${rb.ok}%.`,
 onSubmit:v=>{const p={};rb.params.forEach(q=>p[q.k]=v["p_"+q.k]);startRun(rb,p,!!v.__dry,v.__link);return {toast:"Started "+rb.ref,audit:"started runbook "+rb.ref}}})}
function rbEdit(rb){const e=!!rb;const ser=s=>s.map(x=>x.t+"|"+x.x).join("\n");
 OF({id:"itom_rbf",title:e?"Edit "+rb.ref:"New runbook",story:"A runbook is a repeatable procedure. Mark risky steps as approval gates and always write the rollback. Link it to the events and incidents it fixes so it is offered at the right time.",submit:e?"Save runbook":"Create runbook",
 fields:[{k:"n",label:"Name",type:"text",req:true,ph:"e.g. Fail over SQL to the secondary"},{k:"own",label:"Owner",type:"people",req:true},{k:"trig",label:"When to use it",type:"text",req:true,ph:"The alert or situation that triggers it"},{k:"risk",label:"Risk",type:"chips",opts:["Low","Medium","High"],req:true},{k:"params",label:"Parameters (one per line: name|default)",type:"longtext",rows:2,ph:"region|West US 2"},{k:"steps",label:"Steps (one per line: auto, manual or approval, then | and the text)",type:"longtext",rows:6,req:true,wide:true,ph:"auto|Check health\napproval|Approve failover\nmanual|Smoke test",help:"Order matters. Drag is not needed: edit the lines."},{k:"apr",label:"Eligible approvers",type:"people",multi:true},{k:"rb",label:"Rollback",type:"longtext",rows:2,ph:"How to undo these steps"},{k:"ev",label:"Link to event groups",type:"multi",opts:GRP.map(g=>[g.id,g.id+" "+g.n.slice(0,28)]),wide:true},{k:"inc",label:"Link to incidents",type:"multi",opts:["INC1"]}],
 defaults:e?{n:rb.n,own:rb.own,trig:rb.trig,risk:rb.risk,params:rb.params.map(p=>p.k+"|"+p.d).join("\n"),steps:ser(rb.steps),apr:rb.apr,rb:rb.rb,ev:rb.links.ev,inc:rb.links.inc}:{risk:"Low",apr:[],ev:[],inc:[],steps:"auto|\napproval|"},
 liveH:v=>{const st=(v.steps||"").split("\n").map(l=>l.trim()).filter(Boolean);const ap=st.filter(l=>/^approval\|/i.test(l)).length;return `<b>${st.length}</b> step${st.length===1?"":"s"}, <b>${ap}</b> approval gate${ap===1?"":"s"}. ${v.risk==="High"&&!ap?'<span class="pill bad">High risk needs an approval gate</span>':""} ${!v.rb?'<span class="pill warn">No rollback written</span>':'<span class="pill good">Rollback present</span>'}`},
 onSubmit:v=>{const steps=(v.steps||"").split("\n").map(l=>l.trim()).filter(Boolean).map(l=>{const m=l.match(/^(auto|manual|approval)\|(.+)$/i);return m?{t:m[1].toLowerCase(),x:m[2].trim()}:null});if(!steps.length||steps.includes(null))return bad("Each step needs the form auto|text, manual|text or approval|text.");if(v.risk==="High"&&!steps.some(s=>s.t==="approval"))return bad("A high-risk runbook needs at least one approval gate.");if(v.risk==="High"&&!v.rb)return bad("A high-risk runbook needs a rollback.");const params=(v.params||"").split("\n").map(l=>l.trim()).filter(Boolean).map(l=>{const q=l.split("|");return {k:q[0],d:q[1]||""}});const o={n:v.n,own:v.own,trig:v.trig,risk:v.risk,params,steps,apr:v.apr||[],rb:v.rb||"None",links:{ev:v.ev||[],inc:v.inc||[]}};if(e)Object.assign(rb,o);else{const n=I.rb.length+1;I.rb.push({id:"RB"+(n),ref:"RB-"+(100+n),ok:100,avg:"n/a",last:"Never",rev:"Today",...o});I.rbSel="RB"+n}render();return {toast:(e?"Saved ":"Created ")+v.n,audit:(e?"edited":"created")+" runbook "+v.n}}})}
