 const lib=`<div class="itom-lib">${I.rb.map(r=>`<button class="itom-ri ${r.id===rb.id?"on":""}" data-itom-rb="${r.id}"><span class="row sp"><b>${r.ref}</b><span class="pill ${r.risk==="High"?"bad":r.risk==="Medium"?"warn":"good"}">${r.risk}</span></span><span>${esc(r.n)}</span><span class="muted small">${r.ok}% success · avg ${r.avg} · reviewed ${r.rev}</span></button>`).join("")}<button class="btn primary" data-itom-newrb>New runbook</button></div>`;
