const DAILY=(()=>{const a=[];for(let i=0;i<30;i++){const wk=(i%7===5||i%7===6)?-.15:.1;a.push(Math.round((3.3+.12*Math.sin(i*.9)+wk+(i>=28?1.87:0))*100)/100)}return a})();
function untagged(){return UNT.reduce((a,u)=>a+u[1],0)*(I.fin.tagFixed?.38:1)}
function showback(){const rec=14.8-untagged(),dsum=DEPT.reduce((a,d)=>a+d[1],0);const rows=DEPT.map(d=>({n:d[0],dir:d[1],bud:d[2],fix:rec*d[1]/dsum,alloc:0}));let allocd=0;
 I.fin.rules.forEach(r=>{const u=UNT.find(x=>x[0]===r.svc);if(!u)return;const amt=u[1]*(I.fin.tagFixed?.38:1);allocd+=amt;if(r.dept==="Split by usage")rows.forEach(x=>x.alloc+=amt*x.dir/dsum);else{const t=rows.find(x=>x.n===r.dept);if(t)t.alloc+=amt}});
 rows.forEach(x=>x.tot=x.dir+x.fix+x.alloc);return {rows,unalloc:Math.max(0,untagged()-allocd),allocd}}
