 const pipes=`<div class="card glass"><div class="cardhead"><div><h3>CI/CD pipelines</h3><span class="muted small" data-role="story">Build, test, scan, deploy. One failing test and one scan finding are holding two releases back.</span></div><button class="btn primary" data-itom-newpipe>Add pipeline</button></div><div class="itom-pl">${D.pipes.map(p=>`<div class="itom-p"><div class="row sp"><div><b>${esc(p.n)}</b> <span class="muted small">${p.prov} · ${esc(p.repo)} · ${p.br}</span><div class="muted small">Run ${p.run} by ${esc(p.by)} at ${p.when}</div></div><button class="btn" data-itom-rerun="${p.id}">Re-run</button></div><div class="itom-st">${p.st.map((s,i)=>`<button class="itom-s ${s[1]}" data-itom-stage="${p.id}:${i}" aria-label="${s[0]} ${STC[s[1]][1]}"><span class="itom-si">${IC(s[1]==="pass"?SI.done:s[1]==="fail"?SI.fail:s[1]==="warn"?"M12 8v5M12 17h.01":s[1]==="run"?SI.running:SI.pending)}</span><b>${s[0]}</b><span class="small">${STC[s[1]][1]}${s[2]&&s[2]!=="-"?" · "+s[2]:""}</span></button>`).join('<i class="itom-arr"></i>')}</div></div>`).join("")}</div></div>`;
